node --input-type=module -e '
import { decideWhatsApp as d } from "./bot.mjs";
const H = 3600e3;
const now = new Date(1767272400e3 + 10 * H); // inbound was 10h ago
const ts = "1767272400";
const c = (o) => ({ optedIn: true, lastInboundTimestamp: ts, ...o });
const cases = [
  ["text open window", { type: "text", contact: c({}) }, { allowed: true, reason: null }],
  ["template no window", { type: "template", contact: c({ lastInboundTimestamp: null }) }, { allowed: true, reason: null }],
  ["template open", { type: "template", contact: c({}) }, { allowed: true, reason: null }],
  ["text not opted in", { type: "text", contact: c({ optedIn: false }) }, { allowed: false, reason: "not_opted_in" }],
  ["template not opted in", { type: "template", contact: c({ optedIn: false }) }, { allowed: false, reason: "not_opted_in" }],
  ["optedIn missing", { type: "template", contact: { lastInboundTimestamp: ts } }, { allowed: false, reason: "not_opted_in" }],
  ["text never inbound", { type: "text", contact: c({ lastInboundTimestamp: null }) }, { allowed: false, reason: "no_inbound_message" }],
  ["text window closed 24h exact", { type: "text", contact: c({}) }, null],
  ["text bad ts", { type: "text", contact: c({ lastInboundTimestamp: "abc" }) }, { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["bad type", { type: "image", contact: c({}) }, { allowed: false, reason: "unsupported_message_type" }],
  ["no contact", { type: "text" }, { allowed: false, reason: "invalid_message" }],
];
let fail = 0;
for (const [name, m, exp] of cases) {
  let n = now;
  if (name.includes("exact")) n = new Date(1767272400e3 + 24 * H);
  const got = d(m, n);
  let ok;
  if (exp === null) ok = got.allowed === false && got.reason === "customer_service_window_closed";
  else ok = JSON.stringify(got) === JSON.stringify(exp);
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
// boundary: 23h59m59s open, 1ms before 24h open, 24h closed
const b = (ms) => d({ type: "text", contact: c({}) }, new Date(1767272400e3 + ms));
console.log("23:59:59", JSON.stringify(b(WIN = 86399e3)));
console.log("24h-1ms", JSON.stringify(b(86400e3 - 1)));
console.log("24h", JSON.stringify(b(86400e3)));
// clock skew: inbound 2s ahead of now -> open; 10 min ahead -> invalid
console.log("skew 2s", JSON.stringify(d({ type: "text", contact: c({}) }, new Date(1767272400e3 - 2e3))));
console.log("skew 10min", JSON.stringify(d({ type: "text", contact: c({}) }, new Date(1767272400e3 - 600e3))));
// ms-looking timestamp treated as seconds would be far future -> invalid
console.log("ms-style ts", JSON.stringify(d({ type: "text", contact: c({ lastInboundTimestamp: "1767272400000" }) }, now)));
console.log("number ts", JSON.stringify(d({ type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, now)));
console.log("failures:", fail);
' 2>&1

